package net.civeira.phylax.features.document.snippetversion.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.document.snippet.domain.SnippetReference;

class SnippetVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property snippet of snippet version ")
  void test_snippet_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", SnippetVO.fromReference("10").getSnippetUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", SnippetVO.tryFromReference("11").getSnippetUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", SnippetVO.tryFromReference("12", fails).getSnippetUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> SnippetVO.tryFrom(null));
    Assertions.assertEquals(SnippetReference.of("one"),
        SnippetVO.from(SnippetReference.of("one")).getSnippet());
    Assertions.assertThrows(ConstraintException.class, () -> SnippetVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + SnippetReference.of("one") + "]",
        SnippetVO.from(SnippetReference.of("one")).toString());
  }
}
